import { Router } from 'express';
import { getConfigManager } from '../services/ConfigManager';
import { isLocalBrowserRequest } from './library/middleware';

export const createInstallRefRouter = (): Router => {
  const router = Router();
  router.get('/auth/install-ref', (req, res) => {
    if (req.headers.origin && !isLocalBrowserRequest(req)) {
      return res.sendStatus(403);
    }
    return res.json({ installRef: getConfigManager().getInstallRef() ?? null });
  });
  return router;
};
